import { assertTelemetryMode } from '../config/telemetryPolicy';
import fs from 'fs';
import path from 'path';
import { spawn } from 'child_process';
import { z } from 'zod';
import { HubDiscovery, type HubRecord } from '../services/HubDiscovery';
import { subprocessEnvironment } from '../utils/subprocessEnvironment';
import { isPidAlive } from '../utils/pid';
import { RIVET_VERSION } from '../config/telemetry';
import { isSupportedServerVersion } from '../services/runtimeVersion';
import { hubPort } from './hubPort';
import { stopRuntimeProcess } from '../services/stopRuntimeProcess';
import { assertPluginContext } from '../hosts/pluginContext';
import { errnoCode } from '../utils/errnoCode';

export interface ConnectedHub {
  url: string;
  token: string;
}
interface HubRequest {
  hub: ConnectedHub;
  endpoint: string;
  method?: string;
  body?: unknown;
  timeoutMs?: number;
  expectedAccountId?: string;
}
export class LibraryRequestError extends Error {
  readonly status: number;
  readonly body: unknown;

  constructor(input: { status: number; body: unknown; message: string }) {
    super(input.message);
    this.name = 'LibraryRequestError';
    this.status = input.status;
    this.body = input.body;
  }
}
export const libraryErrorDetails = (
  error: LibraryRequestError,
): { status: number; code?: string } => {
  const code =
    typeof error.body === 'object' &&
    error.body !== null &&
    'code' in error.body &&
    typeof error.body.code === 'string'
      ? error.body.code
      : undefined;
  return { status: error.status, ...(code ? { code } : {}) };
};
const START_TIMEOUT_MS = 20_000;
const POLL_INTERVAL_MS = 100;
const HEALTH_TIMEOUT_MS = 1_000;
const REQUEST_TIMEOUT_MS = 120_000;

class CoordinatorUpgradeRequired extends Error {}

const connect = async (
  record: HubRecord | null,
  {
    env = process.env,
    isSourceSyncAllowed = false,
  }: { env?: NodeJS.ProcessEnv; isSourceSyncAllowed?: boolean } = {},
): Promise<ConnectedHub | null> => {
  if (!record?.port || !isPidAlive(record.pid)) return null;
  const url = `http://127.0.0.1:${record.port}`;
  let runningVersion: unknown;
  let pluginName: string | undefined;
  let telemetryMode: unknown;
  let isSourceSyncStarted: boolean | undefined;
  try {
    const response = await fetch(`${url}/api/library/health`, {
      headers: { Authorization: `Bearer ${record.token}` },
      signal: AbortSignal.timeout(HEALTH_TIMEOUT_MS),
    });
    if (!response.ok) {
      await response.body?.cancel();
      return null;
    }
    const body = z
      .object({
        pid: z.number(),
        instanceId: z.string(),
        rivetVersion: z.unknown().optional(),
        pluginName: z.string().optional(),
        telemetryMode: z.unknown().optional(),
        isSourceSyncStarted: z.boolean().optional(),
      })
      .safeParse(await response.json());
    if (
      !body.success ||
      body.data.pid !== record.pid ||
      body.data.instanceId !== record.token
    )
      return null;
    runningVersion = body.data.rivetVersion;
    pluginName = body.data.pluginName;
    telemetryMode = body.data.telemetryMode;
    isSourceSyncStarted = body.data.isSourceSyncStarted;
  } catch (error) {
    const cause =
      typeof error === 'object' && error !== null && 'cause' in error
        ? error.cause
        : undefined;
    if (
      !isPidAlive(record.pid) ||
      errnoCode(error) === 'ECONNREFUSED' ||
      errnoCode(cause) === 'ECONNREFUSED'
    )
      return null;
    throw new Error(
      `Could not verify the running Rivet coordinator (PID ${record.pid}) at ${url}. Check this command's localhost access and the coordinator's health, then retry. Its discovery record was preserved.`,
    );
  }
  assertPluginContext(pluginName, env);
  assertTelemetryMode(telemetryMode, env);
  if (!isSupportedServerVersion(RIVET_VERSION, runningVersion)) {
    const version =
      typeof runningVersion === 'string'
        ? `v${runningVersion}`
        : 'an unversioned build';
    throw new CoordinatorUpgradeRequired(
      `The shared Rivet coordinator (PID ${record.pid}) is running ${version}; this CLI requires v${RIVET_VERSION} or newer. Run \`rivet open\` to restart it.`,
    );
  }
  const hub = { url, token: record.token };
  if (isSourceSyncAllowed && isSourceSyncStarted === false)
    await requestHub({
      hub,
      endpoint: '/source-sync/schedule',
      method: 'PUT',
    });
  return hub;
};

export const findHub = async (root: string): Promise<ConnectedHub | null> => {
  const discovery = await HubDiscovery.open(root);
  try {
    try {
      return await connect(discovery.read());
    } catch (error) {
      if (!(error instanceof CoordinatorUpgradeRequired)) throw error;
      return await ensureHub({ root, isSourceSyncAllowed: false });
    }
  } finally {
    discovery.close();
  }
};

export const waitForHub = async ({
  discovery,
  isStopped = () => false,
  timeoutMs = START_TIMEOUT_MS,
  env = process.env,
  isSourceSyncAllowed = false,
}: {
  discovery: HubDiscovery;
  isStopped?: () => boolean;
  timeoutMs?: number;
  env?: NodeJS.ProcessEnv;
  isSourceSyncAllowed?: boolean;
}): Promise<ConnectedHub | null> => {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const hub = await connect(discovery.read(), { env, isSourceSyncAllowed });
    if (hub) return hub;
    if (isStopped()) {
      const owner = discovery.read();
      if (!owner || !isPidAlive(owner.pid)) return null;
    }
    await new Promise((resolve) => setTimeout(resolve, POLL_INTERVAL_MS));
  }
  return null;
};

export const ensureHub = async ({
  root,
  env = process.env,
  recordedOwnerTimeoutMs = START_TIMEOUT_MS,
  isSourceSyncAllowed = true,
}: {
  root: string;
  env?: NodeJS.ProcessEnv;
  recordedOwnerTimeoutMs?: number;
  isSourceSyncAllowed?: boolean;
}): Promise<ConnectedHub> => {
  const discovery = await HubDiscovery.open(root);
  try {
    const initial = discovery.read();
    let connected: ConnectedHub | null;
    try {
      connected = await connect(initial, { env, isSourceSyncAllowed });
    } catch (error) {
      if (
        !(error instanceof CoordinatorUpgradeRequired) ||
        !initial ||
        initial.pid === process.pid
      )
        throw error;
      await stopRuntimeProcess({
        pid: initial.pid,
        isOwned: async () => {
          const current = discovery.read();
          if (current?.pid !== initial.pid || current.token !== initial.token)
            return false;
          try {
            await connect(initial, { env });
            return false;
          } catch (failure) {
            return failure instanceof CoordinatorUpgradeRequired;
          }
        },
      });
      connected = null;
    }
    if (connected) return connected;
    if (initial?.port === null && isPidAlive(initial.pid)) {
      const starting = await waitForHub({
        discovery,
        timeoutMs: recordedOwnerTimeoutMs,
        env,
        isSourceSyncAllowed,
      });
      if (starting) return starting;
    }
    if (initial) discovery.discard(initial);
    const current = discovery.read();
    if (!current || !isPidAlive(current.pid)) {
      const logPath = path.join(root, 'runtime', 'coordinator.log');
      const port = hubPort(env);
      fs.mkdirSync(path.dirname(logPath), { recursive: true, mode: 0o700 });
      const logOffset = fs.existsSync(logPath) ? fs.statSync(logPath).size : 0;
      const output = fs.openSync(logPath, 'a', 0o600);
      let childExited = false;
      try {
        const child = spawn(
          process.execPath,
          [
            path.resolve(__dirname, '../../bin/rivet.js'),
            '__hub',
            ...(isSourceSyncAllowed ? [] : ['--no-source-sync']),
          ],
          {
            detached: true,
            stdio: ['ignore', output, output],
            env: {
              ...subprocessEnvironment('rivetRuntime', env),
              RIVET_LIBRARY_ROOT: root,
            },
          },
        );
        await new Promise<void>((resolve, reject) => {
          child.once('spawn', resolve);
          child.once('error', reject);
        });
        child.once('exit', () => {
          childExited = true;
        });
        childExited = child.exitCode !== null;
        child.unref();
      } finally {
        fs.closeSync(output);
      }
      const started = await waitForHub({
        discovery,
        isStopped: () => childExited,
        env,
        isSourceSyncAllowed,
      });
      if (started) return started;
      const startupLog = fs.readFileSync(logPath, 'utf8').slice(logOffset);
      if (startupLog.includes('EADDRINUSE'))
        throw new Error(
          `Rivet could not bind localhost:${port}: the port is in use. Stop the other process or set RIVET_LIBRARY_PORT to an available port.`,
        );
      throw new Error(
        `The shared Rivet application did not become ready. See ${logPath}`,
      );
    }
    const hub = await waitForHub({ discovery, env, isSourceSyncAllowed });
    if (hub) return hub;
    throw new Error(
      `The shared Rivet application did not become ready. See ${path.join(root, 'runtime', 'coordinator.log')}`,
    );
  } finally {
    discovery.close();
  }
};

export const requestHub = async <T>({
  hub,
  endpoint,
  method = 'POST',
  body,
  timeoutMs = REQUEST_TIMEOUT_MS,
  expectedAccountId,
}: HubRequest): Promise<T> => {
  const response = await fetch(`${hub.url}/api/library${endpoint}`, {
    signal: AbortSignal.timeout(timeoutMs),
    method,
    headers: {
      Authorization: `Bearer ${hub.token}`,
      'Content-Type': 'application/json',
      ...(expectedAccountId ? { 'X-Rivet-Account-Id': expectedAccountId } : {}),
    },
    body: JSON.stringify(body),
  });
  const context = `Shared Rivet coordinator ${method} /api/library${endpoint} (HTTP ${response.status})`;
  const responseText = await response.text();
  let result: unknown;
  try {
    result = JSON.parse(responseText);
  } catch (error) {
    if (!(error instanceof SyntaxError)) throw error;
    throw new Error(
      `${context} returned invalid JSON. Run \`rivet open\` to check coordinator compatibility.`,
    );
  }
  if (!response.ok) {
    const message =
      typeof result === 'object' &&
      result !== null &&
      'error' in result &&
      typeof result.error === 'string'
        ? result.error
        : 'Request failed';
    throw new LibraryRequestError({
      status: response.status,
      body: result,
      message: `${context}: ${message}`,
    });
  }
  return result as T;
};
